function openProject(i,trigger){selected=i;lastTrigger=trigger;const p=projects[i];$('#project-title').textContent=p.title;$('#project-description').textContent=p.description;$('#project-number').textContent=`PROJECT 0${i+1} / THE CONSTELLATION`;$('#project-open').href=p.url;$('#project-icon').style.background=`radial-gradient(circle at 30% 25%,#eef3ff,${p.color} 40%,#343858 70%)`;document.body.classList.add('detail-open');detail.showModal();}
function closeProject(){if(detail.open)detail.close();}
detail.querySelector('.close-dialog').onclick=closeProject;detail.querySelector('.back-action').onclick=closeProject;
detail.addEventListener('close',()=>{selected=-1;document.body.classList.remove('detail-open');lastTrigger?.focus({preventScroll:true});});
function updateMotion(){const b=$('#motion');b.textContent=paused?'▷':'Ⅱ';b.setAttribute('aria-label',paused?'Resume animation':'Pause animation');b.setAttribute('aria-pressed',String(paused));}
$('#motion').onclick=()=>{paused=!paused;updateMotion();};reduced.addEventListener('change',e=>{paused=e.matches;updateMotion();});updateMotion();
$('#zoom-in').onclick=()=>zoom=Math.max(-6,zoom-2);$('#zoom-out').onclick=()=>zoom=Math.min(10,zoom+2);$('#reset-view').onclick=()=>{targetYaw=0;targetTilt=0;zoom=0;};
let colorMode=0;$('#color').onclick=()=>{colorMode=(colorMode+1)%3;if(starMaterial)starMaterial.uniforms.uPalette.value=colorMode;if(dustMaterial)dustMaterial.uniforms.uPalette.value=colorMode;$('#color').style.filter=`hue-rotate(${colorMode*65}deg)`;};
let seed=421;function rand(){seed=(seed*1664525+1013904223)>>>0;return seed/4294967296;}function gaussian(){return Math.sqrt(-2*Math.log(Math.max(rand(),.00001)))*Math.cos(6.28318*rand());}
function particleMaterial(dust=false){return new THREE.ShaderMaterial({transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,uniforms:{uTime:{value:0},uPixelRatio:{value:1},uPalette:{value:0},uAlpha:{value:dust?.15:.86}},vertexShader:`attribute float aSize;attribute vec3 aColor;attribute float aPhase;varying vec3 vColor;varying float vPhase;uniform float uTime;uniform float uPixelRatio;void main(){vec3 p=position;float breath=1.0+sin(uTime*.23+length(p)*.5)*.012;p*=breath;vec4 mv=modelViewMatrix*vec4(p,1.);gl_Position=projectionMatrix*mv;gl_PointSize=clamp(aSize*uPixelRatio*(230./-mv.z),.65,${dust?'160.':'14.'});vColor=aColor;vPhase=aPhase;}`,fragmentShader:`varying vec3 vColor;varying float vPhase;uniform float uTime;uniform float uPalette;uniform float uAlpha;void main(){float d=length(gl_PointCoord-.5)*2.;if(d>1.)discard;float a=${dust?'exp(-d*d*5.)*pow(1.-d,1.3)':'pow(1.-d,2.6)'};vec3 c=vColor;if(uPalette>1.5)c=vec3(c.r*.95+c.b*.28,c.g*.78,c.b*.55);else if(uPalette>.5)c=vec3(c.b*.86,c.r*.8,c.g*1.2);float twinkle=.84+.16*sin(uTime*.7+vPhase);gl_FragColor=vec4(c,a*uAlpha*twinkle);}`});}
function createParticles(count,dust){const pos=new Float32Array(count*3),col=new Float32Array(count*3),size=new Float32Array(count),phase=new Float32Array(count);for(let i=0;i<count;i++){const r=Math.pow(rand(),.75)*9.6;const arm=i%4;const spread=gaussian()*(.12+.34*r/9.6);const a=arm*Math.PI/2+r*.69+spread;const scattered=rand()<.14;const th=scattered?rand()*Math.PI*2:a;const rr=scattered?r*.94:r;pos[i*3]=Math.cos(th)*rr+gaussian()*.07;pos[i*3+1]=gaussian()*(.055+Math.exp(-r*.6)*.32)+Math.sin(th*2+r)*.025;pos[i*3+2]=Math.sin(th)*rr+gaussian()*.07;let c=new THREE.Color();const hot=Math.exp(-r*.6);c.setRGB(.28+hot*.65+rand()*.15,.35+hot*.58+rand()*.15,.8+hot*.2);if(arm%2===0&&r>2)c.setRGB(.3+hot*.6,.48+hot*.4,.95);col.set([c.r,c.g,c.b],i*3);size[i]=dust?(1+rand()*2.7):(.045+Math.pow(rand(),5)*.28);phase[i]=rand()*30;}const geo=new THREE.BufferGeometry();geo.setAttribute('position',new THREE.BufferAttribute(pos,3));geo.setAttribute('aColor',new THREE.BufferAttribute(col,3));geo.setAttribute('aSize',new THREE.BufferAttribute(size,1));geo.setAttribute('aPhase',new THREE.BufferAttribute(phase,1));const mat=particleMaterial(dust);const points=new THREE.Points(geo,mat);points.frustumCulled=false;galaxy.add(points);return mat;}
function glowTexture(){const c=document.createElement('canvas');c.width=c.height=128;const ctx=c.getContext('2d');const g=ctx.createRadialGradient(64,64,0,64,64,64);g.addColorStop(0,'rgba(255,255,255,1)');g.addColorStop(.07,'rgba(210,223,255,.9)');g.addColorStop(.2,'rgba(135,157,255,.35)');g.addColorStop(.5,'rgba(105,101,255,.08)');g.addColorStop(1,'rgba(50,60,130,0)');ctx.fillStyle=g;ctx.fillRect(0,0,128,128);return new THREE.CanvasTexture(c);}
const planetVertex=`varying vec3 vNormal;varying vec3 vWorld;varying vec3 vPos;void main(){vNormal=normalize(mat3(modelMatrix)*normal);vWorld=(modelMatrix*vec4(position,1.)).xyz;vPos=position;gl_Position=projectionMatrix*modelViewMatrix*vec4(position,1.);}`;
const planetFragment=`uniform vec3 uColor;uniform float uTime;varying vec3 vNormal;varying vec3 vWorld;varying vec3 vPos;float hash(vec3 p){return fract(sin(dot(p,vec3(127.1,311.7,74.7)))*43758.5453);}float noise(vec3 p){vec3 i=floor(p),f=fract(p);f=f*f*(3.-2.*f);return mix(mix(mix(hash(i),hash(i+vec3(1,0,0)),f.x),mix(hash(i+vec3(0,1,0)),hash(i+vec3(1,1,0)),f.x),f.y),mix(mix(hash(i+vec3(0,0,1)),hash(i+vec3(1,0,1)),f.x),mix(hash(i+vec3(0,1,1)),hash(i+vec3(1,1,1)),f.x),f.y),f.z);}void main(){vec3 n=normalize(vNormal),view=normalize(cameraPosition-vWorld);float clouds=noise(vPos*5.+vec3(uTime*.02,0.,0.))*.55+noise(vPos*12.)*.28+noise(vPos*29.)*.17;float bands=sin(vPos.y*20.+clouds*9.)*.5+.5;float light=max(dot(n,normalize(vec3(-1.,.7,1.))),0.);vec3 surface=mix(uColor*.16,uColor*1.15,smoothstep(.25,.75,clouds*.65+bands*.35));surface*=light*.85+.13;float rim=pow(1.-max(dot(n,view),0.),3.);surface+=uColor*rim*.85;gl_FragColor=vec4(surface,1.);}`;
function init(){scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(45,innerWidth/innerHeight,.1,180);try{renderer=new THREE.WebGLRenderer({antialias:false,alpha:false,powerPreference:'high-performance'});}catch{renderer=new CanvasGalaxyRenderer();}renderer.setClearColor(0x05060d);renderer.setPixelRatio(Math.min(devicePixelRatio,mobile()?1.5:1.8));renderer.setSize(innerWidth,innerHeight);renderer.outputColorSpace=THREE.SRGBColorSpace;$('#space').append(renderer.domElement);galaxy=new THREE.Group();scene.add(galaxy);starMaterial=createParticles(renderer.isFallback?22000:(mobile()?55000:130000),false);dustMaterial=createParticles(renderer.isFallback?600:(mobile()?1800:4800),true);const tex=glowTexture();core=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,color:0xcdd9ff,transparent:true,blending:THREE.AdditiveBlending,depthWrite:false,opacity:.88}));core.scale.set(4.5,3,1);galaxy.add(core);
const bgPos=[],bgCol=[];for(let i=0;i<2100;i++){const a=rand()*Math.PI*2;const y=rand()*2-1;const r=40+rand()*40;bgPos.push(Math.cos(a)*Math.sqrt(1-y*y)*r,y*r,Math.sin(a)*Math.sqrt(1-y*y)*r);const v=.25+rand()*.45;bgCol.push(v*.8,v*.85,v);}const bgGeo=new THREE.BufferGeometry();bgGeo.setAttribute('position',new THREE.Float32BufferAttribute(bgPos,3));bgGeo.setAttribute('color',new THREE.Float32BufferAttribute(bgCol,3));stars=new THREE.Points(bgGeo,new THREE.PointsMaterial({size:.045,vertexColors:true,transparent:true,opacity:.7,depthWrite:false}));scene.add(stars);
planetGroup=new THREE.Group();galaxy.add(planetGroup);
projects.forEach((p,i)=>{const g=new THREE.Group();g.position.set(...p.position);planetGroup.add(g);const material=new THREE.ShaderMaterial({vertexShader:planetVertex,fragmentShader:planetFragment,uniforms:{uColor:{value:new THREE.Color(p.color)},uTime:{value:0}}});const mesh=new THREE.Mesh(new THREE.SphereGeometry(.28+i*.014,48,32),material);g.add(mesh);const glow=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,color:p.color,transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,opacity:.9}));glow.scale.setScalar(1.8);g.add(glow);const orbitPoints=[];for(let j=0;j<=180;j++){const a=j/180*Math.PI*2;orbitPoints.push(new THREE.Vector3(Math.cos(a)*(.56+i*.025),Math.sin(a)*.06,Math.sin(a)*(.56+i*.025)));}const ring=new THREE.Line(new THREE.BufferGeometry().setFromPoints(orbitPoints),new THREE.LineBasicMaterial({color:p.color,transparent:true,opacity:.32}));ring.rotation.z=.25;g.add(ring);
const smallPoints=[new THREE.Vector3(0,0,0),new THREE.Vector3(.6,.06,.8),new THREE.Vector3(1.15,-.05,.35),new THREE.Vector3(1.7,.1,.95)];g.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(smallPoints),new THREE.LineBasicMaterial({color:0x8d99d7,transparent:true,opacity:.25})));smallPoints.slice(1).forEach(v=>{const s=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,color:p.color,transparent:true,depthWrite:false,blending:THREE.AdditiveBlending,opacity:.9}));s.position.copy(v);s.scale.setScalar(.21);g.add(s);});planets.push({group:g,mesh,glow,ring});});
// Pre-formed perimeter constellation and fine orbital tracks.
const path=projects.map(p=>new THREE.Vector3(...p.position));path.push(path[0]);const link=new THREE.Line(new THREE.BufferGeometry().setFromPoints(path),new THREE.LineDashedMaterial({color:0x7d87bf,transparent:true,opacity:.13,dashSize:.07,gapSize:.12}));link.computeLineDistances();planetGroup.add(link);
[7.8,9.7,11.5].forEach((r,i)=>{const pts=[];for(let j=0;j<=360;j++){const a=j/360*Math.PI*2;pts.push(new THREE.Vector3(Math.cos(a)*r,-.08,Math.sin(a)*r));}galaxy.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),new THREE.LineBasicMaterial({color:0x7f83d1,transparent:true,opacity:i===2?.07:.035})));});
camera.position.set(0,6,12);camera.lookAt(-2,0,0);resize();renderer.domElement.addEventListener('webglcontextlost',e=>{e.preventDefault();$('#fallback').hidden=false;});renderer.domElement.addEventListener('webglcontextrestored',()=>location.reload());setupDrag();requestAnimationFrame(frame);}
function setupDrag(){let down=false,x=0,y=0;const el=$('#space');el.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;down=true;x=e.clientX;y=e.clientY;el.setPointerCapture(e.pointerId);el.classList.add('dragging');});el.addEventListener('pointermove',e=>{if(!down||selected>=0)return;targetYaw+=(e.clientX-x)*.004;targetTilt=Math.max(-.35,Math.min(.35,targetTilt+(e.clientY-y)*.002));x=e.clientX;y=e.clientY;});function end(){down=false;el.classList.remove('dragging');}el.addEventListener('pointerup',end);el.addEventListener('pointercancel',end);el.addEventListener('lostpointercapture',end);
// Two-finger orbit keeps ordinary one-finger page scrolling available.
let touchX=0;el.addEventListener('touchstart',e=>{if(e.touches.length===2)touchX=(e.touches[0].clientX+e.touches[1].clientX)/2;},{passive:true});el.addEventListener('touchmove',e=>{if(e.touches.length===2){e.preventDefault();const now=(e.touches[0].clientX+e.touches[1].clientX)/2;targetYaw+=(now-touchX)*.006;touchX=now;}},{passive:false});}
function resize(){if(!renderer)return;renderer.setSize(innerWidth,innerHeight);camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();starMaterial.uniforms.uPixelRatio.value=renderer.getPixelRatio();dustMaterial.uniforms.uPixelRatio.value=renderer.getPixelRatio();}
addEventListener('resize',resize);const targetCamera=new THREE.Vector3(),look=new THREE.Vector3(-2,0,0),targetLook=new THREE.Vector3(),world=new THREE.Vector3(),projected=new THREE.Vector3();
function frame(now){requestAnimationFrame(frame);const dt=Math.min((now-last)/1000,.15);last=now;if(document.hidden)return;if(!paused&&selected<0)time+=dt;scrollProgress=Math.min(1,scrollY/(document.documentElement.scrollHeight-innerHeight));const ease=reduced.matches?1:1-Math.exp(-dt*4);smoothProgress+=(scrollProgress-smoothProgress)*ease;yaw+=(targetYaw-yaw)*ease;tilt+=(targetTilt-tilt)*ease;const p=smoothProgress;galaxy.rotation.y=yaw+time*.014;galaxy.rotation.x=tilt;starMaterial.uniforms.uTime.value=time;dustMaterial.uniforms.uTime.value=time;core.scale.set(4.5+Math.sin(time*.4)*.12,3+Math.sin(time*.4)*.08,1);const far=mobile()?43:28;const distance=Math.max(3,4.8+(far-4.8)*p+zoom);const elevation=.25+p*.35;const shift=mobile()?0:-.8*(1-Math.min(p/.82,1));targetLook.set(shift,0,0);targetCamera.set(shift,Math.sin(elevation)*distance,Math.cos(elevation)*distance);
if(mobile()&&p<.75){targetLook.y=-1.3;targetCamera.y+=1.1;}
if(selected>=0){planets[selected].group.getWorldPosition(world);targetLook.copy(world);targetLook.x-=mobile()?0:.95;targetLook.y-=mobile()?.6:0;targetCamera.copy(world).add(new THREE.Vector3(mobile()?0:1.1,mobile()?1.6:1.4,mobile()?3.8:4.1));}
camera.position.lerp(targetCamera,reduced.matches?1:1-Math.exp(-dt*2.7));look.lerp(targetLook,reduced.matches?1:1-Math.exp(-dt*3));camera.lookAt(look);galaxy.updateMatrixWorld(true);camera.updateMatrixWorld(true);
planets.forEach((o,i)=>{o.mesh.rotation.y=time*.09+i;o.mesh.material.uniforms.uTime.value=time;const want=hover===i?1.28:1;o.mesh.scale.lerp(new THREE.Vector3(want,want,want),ease);o.glow.material.opacity=hover===i?1.2:.7;o.ring.rotation.y=time*.04;const b=labels[i];o.group.getWorldPosition(world);projected.copy(world).project(camera);const visible=selected<0&&p>.78&&projected.z<1&&Math.abs(projected.x)<.93&&Math.abs(projected.y)<.82; b.hidden=!visible;if(visible){b.style.transform=`translate(${(projected.x*.5+.5)*innerWidth}px,${(-projected.y*.5+.5)*innerHeight}px) translate(-50%,${mobile()?-22:-31}px)`;b.style.opacity=String(Math.min(1,(p-.78)*7));}});
updateChapters(p);renderer.render(scene,camera);}
try{init();}catch(e){console.error('Galaxy initialization failed',e);$('#fallback').hidden=false;}

function updateChapters(p){const stages=[p<.25, p>.32&&p<.65,p>.83];document.querySelectorAll('.chapter').forEach((el,i)=>{el.classList.toggle('active',stages[i]);el.inert=!stages[i];});$('#scroll-label').textContent=p>.9?'SCROLL TO RETURN':'SCROLL TO ZOOM OUT';}
